#:sdk Microsoft.NET.Sdk.Web #:package MessagePack@2.5.122 #:package System.IO.Pipelines@8.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using System.IO.Pipelines; using MessagePack;  public class ZeroCopyMessagePackSerializer : IAsyncDisposable {     private readonly Pipe _pipe;     private readonly MemoryPool<byte> _memoryPool;     private readonly Task _processingTask;     private readonly CancellationTokenSource _cts = new();      public ZeroCopyMessagePackSerializer()     {         _memoryPool = MemoryPool<byte>.Shared;         _pipe = new Pipe(new PipeOptions(             pool: _memoryPool,             minimumSegmentSize: 4096));          _processingTask = Task.Run(ProcessPipeAsync);     }      public async ValueTask SerializeAsync<T>(T value)     {         var writer = new MessagePackWriter(_pipe.Writer);         MessagePackSerializer.Serialize(ref writer, value);         await writer.FlushAsync(_cts.Token);         await _pipe.Writer.FlushAsync(_cts.Token);     }      public async ValueTask<T?> DeserializeAsync<T>()     {         var result = await MessagePackSerializer.DeserializeAsync<T>(             _pipe.Reader.AsStream(),             cancellationToken: _cts.Token);         return result;     }      private async Task ProcessPipeAsync()     {         while (!_cts.IsCancellationRequested)         {             var readResult = await _pipe.Reader.ReadAsync(_cts.Token);             if (readResult.IsCompleted || readResult.IsCanceled)                 break;              _pipe.Reader.AdvanceTo(readResult.Buffer.End);         }     }      public async ValueTask DisposeAsync()     {         _cts.Cancel();         await _processingTask;         _pipe.Reader.Complete();         _pipe.Writer.Complete();     } }
